/**
 * Convenience generator used by the per-topic exit-quiz UX (mirrors other courses).
 */
/** This pool honours the AP track mixes (track-mix.ts); index.ts reads the flag. */
export const supportsTrackMix = true

export function generateExitQuiz(count = 10, topicSlug?: string, difficulty?: string) {
  let pool = apPrecalcQuestionPool
  if (topicSlug) pool = relevantPool(pool, topicSlug)
  // Untracked: the plain shuffle, unchanged (old attempts replay exactly).
  return drawWithTrackMix(pool, count, difficulty, () => shuffleArray(pool).slice(0, count))
    .map((q, i) => ({
      id: `${q.topicSlug}-q${i}`,
      question: q.question,
      options: q.options,
      correctIndex: q.correctAnswer,
      explanation: q.explanation,
      category: q.domain,
      topicSlug: q.topicSlug,
      partNumber: q.part,
    }))
}
